1	import React, { createContext, useContext, useState, useEffect, ReactNode, useRef } from 'react';
2	import { useAuth } from '@/shared/hooks/useAuth';
3	import { usePermissions } from '@/shared/hooks/usePermissions';
4	import { supabase } from '@/integrations/supabase/client';
5	import { wideInfo, wideDebug, wideWarn, wideError } from '@/shared/lib/telemetry/wide-events';
6	import { recordStoreChange, recordStoreChangeDuration } from '@/shared/lib/telemetry/metrics';
7	import { recordRumStoreChange } from '@/shared/lib/telemetry/rum';
8	import { handleError } from '@/shared/lib/error-handler';
9	
10	interface Store {
11	  id: number;
12	  name: string;
13	  address: string;
14	  shortName: string;
15	  tipo?: string; // 'Loja' | 'Fabrica' (do banco) - opcional para fallback
16	}
17	
18	interface StoreContextType {
19	  selectedStore: Store | null;
20	  setSelectedStore: (store: Store) => void;
21	  // Forçar seleção programática (ignora permissões) - útil para páginas exclusivas da Fábrica
22	  forceSetSelectedStore: (predicate: (s: Store) => boolean) => void;
23	  stores: Store[];
24	  loading: boolean;
25	  canChangeStore: boolean;
26	}
27	
28	// Lista predefinida de lojas (fallback caso não consiga carregar do banco)
29	// IDs atualizados conforme migration 20260303120000_reorganize_store_ids_add_brasilia_shopping
30	const STORES: Store[] = [
31	  { id: 1, name: 'Fábrica', address: 'Brasília - DF', shortName: 'Fábrica', tipo: 'Fabrica' },
32	  { id: 2, name: 'Momma Asa Sul', address: 'Brasília - DF', shortName: 'Asa Sul', tipo: 'Loja' },
33	  { id: 3, name: 'Momma Asa Norte', address: 'Asa Norte, Brasília - DF', shortName: 'Asa Norte', tipo: 'Loja' },
34	  { id: 4, name: 'Momma Lago Sul', address: 'Brasília - DF, Lago Sul', shortName: 'Lago Sul', tipo: 'Loja' },
35	  { id: 5, name: 'Momma Águas Claras', address: 'Águas Claras, Brasília - DF', shortName: 'Águas Claras', tipo: 'Loja' },
36	  { id: 6, name: 'Momma Brasília Shopping', address: 'Brasília Shopping, Brasília - DF', shortName: 'Brasília Shopping', tipo: 'Loja' }
37	];
38	
39	// NOTA: Todos os dados existentes (produtos, movimentações, etc.)
40	// pertencem à loja Asa Sul. As lojas Lago Sul e Asa Norte
41	// ainda não possuem dados ou movimentações.
42	
43	const StoreContext = createContext<StoreContextType | undefined>(undefined);
44	
45	interface StoreProviderProps {
46	  children: ReactNode;
47	}
48	
49	export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
50	  const { user, userProfile } = useAuth();
51	  const { isAdmin, canSwitchStore } = usePermissions();
52	  const [selectedStore, setSelectedStoreState] = useState<Store | null>(null);
53	  const [loading, setLoading] = useState(true);
54	  const [canChangeStore, setCanChangeStore] = useState(false);
55	  const [availableStores, setAvailableStores] = useState<Store[]>(STORES);
56	
57	  // Carregar lojas do banco de dados
58	  const loadStoresFromDB = async () => {
59	    wideDebug('store.load_stores_start', 'Iniciando carregamento de lojas do banco', {
60	      attributes: { 'store.source': 'supabase' },
61	    });
62	    try {
63	      const { data, error } = await supabase
64	        .from('lojas')
65	        .select('id, nome, endereco, tipo')
66	        .eq('ativo', true)
67	        .order('nome');
68	
69	      if (error) {
70	        wideError('store.load_stores_error', 'Erro ao carregar lojas do Supabase', {
71	          attributes: {
72	            'store.error_code': error.code,
73	            'store.error_message': error.message,
74	          },
75	        });
76	        throw error;
77	      }
78	
79	      const storeCount = data?.length || 0;
80	      const formattedStores = data?.map(store => {
81	        // Gerar shortName baseado no nome da loja
82	        let shortName = store.nome;
83	        if (store.nome.startsWith('Momma ')) {
84	          shortName = store.nome.replace('Momma ', '');
85	        }
86	        if (store.nome.toLowerCase().includes('fábrica') || store.tipo === 'Fabrica') {
87	          shortName = 'Fábrica';
88	        }
89	
90	        return {
91	          id: store.id,
92	          name: store.nome,
93	          address: store.endereco,
94	          shortName: shortName,
95	          tipo: store.tipo
96	        };
97	      }) || STORES;
98	
99	      wideDebug('store.load_stores_success', `Lojas carregadas: ${storeCount}`, {
100	        attributes: {
101	          'store.count': storeCount,
102	          'store.source': 'supabase',
103	        },
104	      });
105	      setAvailableStores(formattedStores);
106	      return formattedStores;
107	    } catch (error) {
108	      handleError(error, { domain: 'store', operation: 'loadStoresFromDB', showToast: false });
109	      wideDebug('store.load_stores_fallback', 'Usando lojas predefinidas como fallback', {
110	        attributes: { 'store.fallback_count': STORES.length },
111	      });
112	      return STORES; // Fallback para lojas predefinidas
113	    }
114	  };
115	
116	  // Carregar loja selecionada do localStorage ou perfil do usuário
117	  const loadSelectedStore = (stores: Store[]): Store | null => {
118	    wideDebug('store.select_start', 'Iniciando seleção de loja', {
119	      attributes: {
120	        'store.has_user_profile': !!userProfile,
121	        'store.can_change_store': userProfile?.can_change_store ?? false,
122	        'store.default_store_id': userProfile?.default_store_id ?? 0,
123	        'store.available_count': stores.length,
124	        'store.is_admin': isAdmin(),
125	      },
126	    });
127	
128	    // Para usuários que NÃO podem alterar loja (não-admin), sempre usar default_store_id
129	    if (!canSwitchStore() && !userProfile?.can_change_store) {
130	      if (userProfile?.default_store_id) {
131	        const userStore = stores.find(s => s.id === userProfile.default_store_id);
132	        if (userStore) {
133	          localStorage.setItem('selectedStore', JSON.stringify(userStore));
134	          return userStore;
135	        }
136	      }
137	      // Fallback: Tentar recuperar do localStorage se o perfil ainda não carregou (estado transiente)
138	      // Isso evita que o usuário "caia" na Fábrica enquanto o perfil carrega
139	      if (!userProfile) {
140	        try {
141	          const saved = localStorage.getItem('selectedStore');
142	          if (saved) {
143	            const parsed = JSON.parse(saved);
144	            const store = stores.find(s => s.id === parsed.id);
145	            if (store) {
146	              wideDebug('store.select_cache', 'Sem perfil: usando cache local temporário', {
147	                attributes: { 'store.name': store.name, 'store.id': store.id },
148	              });
149	              return store;
150	            }
151	          }
152	        } catch (e) {
153	          handleError(e, { domain: 'store', operation: 'loadSelectedStore.localStorageFallback', showToast: false });
154	        }
155	      }
156	
157	      // Fallback imediato: selecionar Fábrica quando perfil ainda não carregou ou loja padrão inválida
158	      const fabrica = stores.find(s => s.shortName === 'Fábrica' || s.name.toLowerCase().includes('fábrica'));
159	      if (fabrica) {
160	        localStorage.setItem('selectedStore', JSON.stringify(fabrica));
161	        return fabrica;
162	      }
163	      return null;
164	    }
165	
166	    // Para admins/operações gerais ou usuários com permissão de alterar loja: usar localStorage primeiro
167	    if (canSwitchStore() || userProfile?.can_change_store) {
168	      // PRIORIDADE 1: Tentar carregar do localStorage primeiro (preservar contexto)
169	      try {
170	        const saved = localStorage.getItem('selectedStore');
171	        if (saved) {
172	          const parsed = JSON.parse(saved);
173	          const store = stores.find(s => s.id === parsed.id);
174	          if (store) {
175	            wideDebug('store.select_localStorage', 'Loja preservada do localStorage', {
176	              attributes: { 'store.name': store.name, 'store.id': store.id },
177	            });
178	            return store;
179	          } else {
180	            wideWarn('store.select_localStorage_invalid', 'Loja do localStorage não encontrada nas lojas disponíveis', {
181	              attributes: { 'store.invalid_id': parsed.id },
182	            });
183	            // Limpar localStorage inválido
184	            localStorage.removeItem('selectedStore');
185	          }
186	        }
187	      } catch (error) {
188	        handleError(error, { domain: 'store', operation: 'loadSelectedStore.localStorage', showToast: false });
189	        // Limpar localStorage corrompido
190	        localStorage.removeItem('selectedStore');
191	      }
192	
193	      // PRIORIDADE 2: Se não há localStorage válido, usar loja padrão do perfil
194	      if (userProfile?.default_store_id) {
195	        const userStore = stores.find(s => s.id === userProfile.default_store_id);
196	        if (userStore) {
197	          wideDebug('store.select_profile_default', 'Usando loja padrão do perfil', {
198	            attributes: { 'store.name': userStore.name, 'store.id': userStore.id },
199	          });
200	          // Salvar no localStorage para preservar na próxima vez
201	          localStorage.setItem('selectedStore', JSON.stringify(userStore));
202	          return userStore;
203	        } else {
204	          wideWarn('store.select_profile_invalid', 'Loja padrão do perfil não encontrada', {
205	            attributes: { 'store.default_store_id': userProfile.default_store_id },
206	          });
207	        }
208	      }
209	
210	      // PRIORIDADE 3: Para admins sem loja padrão, usar a primeira loja como fallback
211	      // Isso só acontece para admins que não têm loja padrão configurada
212	      if (stores.length > 0) {
213	        const fallbackStore = stores[0];
214	        wideDebug('store.select_fallback', 'Admin sem loja padrão: usando fallback', {
215	          attributes: { 'store.name': fallbackStore.name, 'store.id': fallbackStore.id },
216	        });
217	        // Salvar no localStorage para preservar na próxima vez
218	        localStorage.setItem('selectedStore', JSON.stringify(fallbackStore));
219	        return fallbackStore;
220	      }
221	    }
222	
223	    wideError('store.select_no_store', 'Nenhuma loja disponível ou usuário sem permissões adequadas', {
224	      attributes: {
225	        'store.available_count': stores.length,
226	        'store.has_user_profile': !!userProfile,
227	      },
228	    });
229	    return null;
230	  };
231	
232	  // Salvar loja selecionada no localStorage (apenas para admins)
233	  const saveSelectedStore = (store: Store) => {
234	    if (canChangeStore) {
235	      try {
236	        localStorage.setItem('selectedStore', JSON.stringify(store));
237	      } catch (error) {
238	        handleError(error, { domain: 'store', operation: 'saveSelectedStore', showToast: false });
239	      }
240	    }
241	  };
242	
243	  // Ref para medir duração do re-render após troca de unidade
244	  const storeChangeMarkRef = useRef<number | null>(null);
245	
246	  const setSelectedStore = (store: Store) => {
247	    wideDebug('store.change_attempt', 'Tentativa de mudança de loja', {
248	      attributes: {
249	        'store.target_name': store.name,
250	        'store.target_id': store.id,
251	        'store.can_change': canChangeStore,
252	        'store.is_admin': isAdmin(),
253	      },
254	    });
255	
256	    // Permitir mudança se o usuário pode alterar loja OU é administrador/operações gerais
257	    if (canChangeStore || canSwitchStore()) {
258	      // Telemetria: emitir wide event de troca de unidade
259	      const previousStore = selectedStore;
260	      if (previousStore && previousStore.id !== store.id) {
261	        wideInfo('store.change', `Troca de unidade: ${previousStore.name} → ${store.name}`, {
262	          attributes: {
263	            'store.from_id': previousStore.id,
264	            'store.from_name': previousStore.name,
265	            'store.to_id': store.id,
266	            'store.to_name': store.name,
267	          },
268	        });
269	        recordStoreChange({ 'store.to_name': store.name });
270	        recordRumStoreChange(store.name);
271	
272	        // Marcar início para medir duração do re-render
273	        storeChangeMarkRef.current = performance.now();
274	      }
275	
276	      setSelectedStoreState(store);
277	      saveSelectedStore(store);
278	    } else {
279	      wideWarn('store.change_blocked', 'Mudança de loja bloqueada — usuário sem permissão', {
280	        attributes: {
281	          'store.target_name': store.name,
282	          'store.target_id': store.id,
283	        },
284	      });
285	    }
286	  };
287	
288	  // Forçar seleção de loja de forma programática (ignora permissões)
289	  const forceSetSelectedStore = (predicate: (s: Store) => boolean) => {
290	    try {
291	      const target = availableStores.find(predicate);
292	      if (target) {
293	        setSelectedStoreState(target);
294	        try {
295	          localStorage.setItem('selectedStore', JSON.stringify(target));
296	        } catch (e) {
297	          handleError(e, { domain: 'store', operation: 'forceSetSelectedStore.localStorage', showToast: false });
298	        }
299	      }
300	    } catch (e) {
301	      handleError(e, { domain: 'store', operation: 'forceSetSelectedStore', showToast: false });
302	    }
303	  };
304	
305	  // MIA Glass-Box — escuta evento `mia:switch-store` e troca loja via context.
306	  // Usado quando StoreSelector não está visível na rota atual (mobile, modais).
307	  // Normaliza nome usando shortName, name e variações comuns.
308	  useEffect(() => {
309	    const handler = (e: Event) => {
310	      const detail = (e as CustomEvent<{ name: string }>).detail;
311	      const target = detail?.name?.toString().trim();
312	      if (!target) return;
313	      const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
314	      const t = norm(target);
315	      const found = availableStores.find(s =>
316	        norm(s.name) === t ||
317	        norm(s.shortName) === t ||
318	        norm(s.name).includes(t) ||
319	        norm(s.shortName).includes(t) ||
320	        t.includes(norm(s.shortName))
321	      );
322	      if (found) {
323	        setSelectedStore(found);
324	      } else {
325	        wideWarn('store.mia_switch_no_match', `MIA pediu trocar loja "${target}" mas não bateu`, {
326	          attributes: { 'mia.target': target, 'stores.available': availableStores.length },
327	        });
328	      }
329	    };
330	    window.addEventListener('mia:switch-store', handler);
331	    return () => window.removeEventListener('mia:switch-store', handler);
332	    // eslint-disable-next-line react-hooks/exhaustive-deps
333	  }, [availableStores, canChangeStore]);
334	
335	  // Medir duração do re-render após troca de unidade
336	  useEffect(() => {
337	    if (storeChangeMarkRef.current !== null && selectedStore) {
338	      const durationMs = Math.round(performance.now() - storeChangeMarkRef.current);
339	      storeChangeMarkRef.current = null;
340	
341	      const pageRoute = typeof window !== 'undefined' ? window.location.pathname : '';
342	      wideInfo('store.change.performance', `Re-render após troca de unidade: ${durationMs}ms`, {
343	        attributes: {
344	          'duration_ms': durationMs,
345	          'page.route': pageRoute,
346	        },
347	      });
348	      recordStoreChangeDuration(durationMs);
349	    }
350	  }, [selectedStore]);
351	
352	  // Usar useRef para controlar inicialização sem causar re-renders
353	  const initializationRef = useRef<{
354	    isInitialized: boolean;
355	    currentUserId: string | null;
356	    isInitializing: boolean;
357	    lastUserProfileCheck: string | null;
358	    lastAdminStatus?: boolean;
359	    lastCanChangeStore?: boolean;
360	    profileLoaded?: boolean;
361	  }>({ isInitialized: false, currentUserId: null, isInitializing: false, lastUserProfileCheck: null });
362	
363	  // Separar o useEffect para evitar loops
364	  useEffect(() => {
365	    wideDebug('store.context_reset_check', 'Verificando reset de contexto', {
366	      attributes: {
367	        'store.user_id': user?.id || '',
368	        'store.current_user_id': initializationRef.current.currentUserId || '',
369	      },
370	    });
371	
372	    // Reset quando não há usuário
373	    if (!user) {
374	      wideDebug('store.context_reset', 'Resetando contexto — usuário deslogado', {
375	        attributes: { 'store.reason': 'no_user' },
376	      });
377	      setSelectedStoreState(null);
378	      setCanChangeStore(false);
379	      initializationRef.current = {
380	        isInitialized: false,
381	        currentUserId: null,
382	        isInitializing: false,
383	        lastUserProfileCheck: null,
384	        lastAdminStatus: undefined,
385	        lastCanChangeStore: undefined,
386	        profileLoaded: false
387	      };
388	      setLoading(false);
389	      return;
390	    }
391	
392	    // Se mudou de usuário, resetar
393	    if (initializationRef.current.currentUserId && initializationRef.current.currentUserId !== user.id) {
394	      wideDebug('store.context_reset', 'Resetando contexto — usuário mudou', {
395	        attributes: {
396	          'store.previous_user_id': initializationRef.current.currentUserId || '',
397	          'store.new_user_id': user.id,
398	        },
399	      });
400	      initializationRef.current = {
401	        isInitialized: false,
402	        currentUserId: null,
403	        isInitializing: false,
404	        lastUserProfileCheck: null
405	      };
406	      setSelectedStoreState(null);
407	      setCanChangeStore(false);
408	    }
409	  }, [user?.id]); // Usar apenas user?.id como dependência
410	
411	  // Extrai resultado de canSwitchStore para evitar chamada de função na deps array
412	  const isAdminUser = canSwitchStore();
413	
414	  // UseEffect separado para inicialização quando userProfile estiver disponível
415	  useEffect(() => {
416	    wideDebug('store.init_check', 'Verificando inicialização de lojas', {
417	      attributes: {
418	        'store.has_user': !!user,
419	        'store.has_user_profile': !!userProfile,
420	        'store.is_initialized': initializationRef.current.isInitialized,
421	        'store.is_initializing': initializationRef.current.isInitializing,
422	      },
423	    });
424	
425	    // Se o userProfile foi carregado depois da inicialização e o usuário é admin,
426	    // verificar se há uma loja no localStorage que deve ser preservada
427	    if (user && userProfile && initializationRef.current.isInitialized &&
428	      initializationRef.current.currentUserId === user.id && canSwitchStore()) {
429	      try {
430	        const saved = localStorage.getItem('selectedStore');
431	        if (saved && selectedStore) {
432	          const parsed = JSON.parse(saved);
433	          // Se a loja do localStorage é diferente da atual, atualizar
434	          if (parsed.id !== selectedStore.id) {
435	            const storeFromStorage = availableStores.find(s => s.id === parsed.id);
436	            if (storeFromStorage) {
437	              wideDebug('store.restore_from_storage', 'Admin: restaurando loja do localStorage após carregamento do userProfile', {
438	                attributes: { 'store.name': storeFromStorage.name, 'store.id': storeFromStorage.id },
439	              });
440	              setSelectedStoreState(storeFromStorage);
441	              return; // Sair cedo para evitar reinicialização
442	            }
443	          }
444	        }
445	      } catch (error) {
446	        handleError(error, { domain: 'store', operation: 'restoreFromStorage', showToast: false });
447	      }
448	    }
449	
450	    // Timeout para evitar loading perpétuo quando userProfile não carrega
451	    let initTimeout: NodeJS.Timeout;
452	
453	    const initializeStore = async (force: boolean = false) => {
454	      wideDebug('store.init_start', 'Iniciando inicialização de loja', {
455	        attributes: {
456	          'store.has_user': !!user,
457	          'store.has_user_profile': !!userProfile,
458	          'store.is_initialized': initializationRef.current.isInitialized,
459	          'store.is_initializing': initializationRef.current.isInitializing,
460	          'store.force': force,
461	        },
462	      });
463	
464	      // Verificação básica - só precisa do user
465	      if (!user) {
466	        setLoading(false);
467	        return;
468	      }
469	
470	      // Se userProfile existe, verificar se são do mesmo usuário
471	      if (userProfile && userProfile.user_id && user.id !== userProfile.user_id) {
472	        wideDebug('store.init_sync_wait', 'user.id !== userProfile.user_id — aguardando sincronização', {
473	          attributes: { 'store.user_id': user.id },
474	        });
475	        setLoading(false);
476	        return;
477	      }
478	
479	      // Se userProfile é null/undefined e NÃO estamos forçando, AGUARDAR
480	      if (!userProfile && !force) {
481	        wideDebug('store.init_waiting_profile', 'userProfile ainda não disponível, aguardando', {
482	          attributes: { 'store.user_id': user.id },
483	        });
484	        // Manter loading=true enquanto aguarda
485	        setLoading(true);
486	        return;
487	      }
488	
489	      // Se estamos aqui e userProfile é null, mas force=true, logar aviso
490	      if (!userProfile && force) {
491	        wideWarn('store.init_force_no_profile', 'Forçando inicialização sem userProfile (timeout atingido)', {
492	          attributes: { 'store.user_id': user.id },
493	        });
494	      }
495	
496	      // Se já está inicializando, não fazer nada
497	      if (initializationRef.current.isInitializing) {
498	        return;
499	      }
500	
501	      // Se já foi inicializado para este usuário, verificar se precisamos re-inicializar
502	      // EXCETO se for force=true (pode ser uma tentativa de recuperação)
503	      const profileNewlyAvailable = userProfile && !initializationRef.current.profileLoaded;
504	
505	      if (initializationRef.current.isInitialized &&
506	        initializationRef.current.currentUserId === user.id &&
507	        !force &&
508	        !profileNewlyAvailable) {
509	        return;
510	      }
511	
512	      wideDebug('store.init_begin', `Iniciando inicialização (Re-init: ${profileNewlyAvailable ? 'Sim (Profile chegou)' : 'Não'})`, {
513	        attributes: {
514	          'store.re_init': !!profileNewlyAvailable,
515	          'store.user_id': user.id,
516	        },
517	      });
518	      initializationRef.current.isInitializing = true;
519	      setLoading(true);
520	
521	      try {
522	        // Determinar se o usuário pode alterar loja
523	        // Administradores SEMPRE podem alterar loja, outros usuários dependem do can_change_store
524	        const isUserAdmin = canSwitchStore();
525	        const userCanChangeStore = isUserAdmin || (userProfile?.can_change_store ?? false);
526	
527	        // FORÇA ADMIN/OPERAÇÕES GERAIS: pode sempre alterar loja
528	        const finalCanChangeStore = userCanChangeStore;
529	
530	        wideDebug('store.init_permissions', 'Permissões de loja calculadas', {
531	          attributes: {
532	            'store.can_change': finalCanChangeStore,
