152	function buildDays(from: Date, count: number) {
153	  const days: { key: string; date: Date; dateISO: string; label: string }[] =
154	    [];
155	  for (let i = 0; i < count; i++) {
156	    const d = new Date(from);
157	    d.setDate(from.getDate() + i);
158	    const weekday = d.toLocaleDateString('pt-BR', {
159	      timeZone: 'America/Sao_Paulo',
160	      weekday: 'short',
161	    });
162	    const label = `${weekday} ${d.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' })}`;
163	    days.push({
164	      key: `${formatDateISO(d)}-${i}`,
165	      date: d,
166	      dateISO: formatDateISO(d),
167	      label,
168	    });
169	  }
170	  return days;
171	}
