  SelectValue,
} from '@/shared/ui/select';
import { useStore } from '@/shared/contexts/StoreContext';
import { toast } from 'sonner';
import {
  DndContext,
  DragEndEvent,
  DragStartEvent,
  DragOverlay,
  useSensors,
  useSensor,
  PointerSensor,
} from '@dnd-kit/core';
import { useDroppable, useDraggable } from '@dnd-kit/core';
import { CSS } from '@dnd-kit/utilities';
import { PermissionBlur } from '@/shared/ui/PermissionBlur';
import { usePermissions } from '@/shared/hooks/usePermissions';
import { useIsMobile, useIsTablet } from '@/shared/hooks/use-mobile';
import { LogisticsOrderModal } from '@/features/logistica/ui/LogisticsOrderModal';
import { withTrace } from '@/shared/lib/telemetry/tracer';
import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
import {
  recordOperation,
  recordError,
  recordOperationDuration,
} from '@/shared/lib/telemetry/metrics';
import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';

interface RequisicaoItem {
  id: number;
  requisicao_id: number;
  nome_produto: string;
  quantidade_solicitada: number;
  quantidade_enviada: string | null;
  observacao: string | null;
  ordem: number;
  created_at?: string;
  lote?: string | null;
  validade?: string | null;
}

interface RequisicaoQueue {
  id: number;
  nome: string;
  solicitante: string;
  loja_solicitante: string;
  loja_preparadora: string;
  data_pedido: string;
  data_recebimento: string;
  created_at: string;
  status: string;
  user_id?: string;
  lancado_por?: string | null;
  requisicoes_itens: RequisicaoItem[];
  subtitle?: string;
  expedicao_id?: string | number | null;
}

function dateISOFromName(name: string) {
  const s = String(name || '');
  const m = s.match(/(\d{2})[/-](\d{2})[/-](\d{2,4})$/);
  if (!m) return null;
  const dd = Number(m[1]);
  const mm = Number(m[2]);
  const yy = m[3].length === 2 ? Number(`20${m[3]}`) : Number(m[3]);
  const d = new Date(yy || 0, (mm || 1) - 1, dd || 1);
  const y = d.getFullYear();
  const mo = String(d.getMonth() + 1).padStart(2, '0');
  const da = String(d.getDate()).padStart(2, '0');
  return `${y}-${mo}-${da}`;
}

function parseISODateLocal(iso: string) {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y || 0, (m || 1) - 1, d || 1, 12, 0, 0, 0);
}

function formatTime(ts: string) {
  const s = String(ts || '');
  let d = new Date(s);
  if (isNaN(d.getTime())) {
    const parts = s.split(/[T\s]/);
    if (parts.length >= 2) {
      const [datePart, timePart] = parts;
      const [yy, mm, dd] = datePart.split('-').map((n) => Number(n));
      const [hh, mi] = timePart.split(':').map((n) => Number(n));
      d = new Date(yy || 0, (mm || 1) - 1, dd || 1, hh || 0, mi || 0, 0);
    } else {
      const [yy, mm, dd] = s.split('-').map((n) => Number(n));
      d = new Date(yy || 0, (mm || 1) - 1, dd || 1);
    }
  }
  return d.toLocaleTimeString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function classNames(...arr: (string | false | undefined)[]) {
  return arr.filter(Boolean).join(' ');
}

function startOfWeek(date = new Date()) {
  const d = new Date(date);
  const day = d.getDay();
  const diff = (day === 0 ? -6 : 1) - day; // segunda-feira
  d.setDate(d.getDate() + diff);
  d.setHours(0, 0, 0, 0);
  return d;
}

function formatDateISO(d: Date) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function buildDays(from: Date, count: number) {
  const days: { key: string; date: Date; dateISO: string; label: string }[] =
    [];
  for (let i = 0; i < count; i++) {
    const d = new Date(from);
    d.setDate(from.getDate() + i);
    const weekday = d.toLocaleDateString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      weekday: 'short',
    });
    const label = `${weekday} ${d.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' })}`;
    days.push({
      key: `${formatDateISO(d)}-${i}`,
      date: d,
      dateISO: formatDateISO(d),
      label,
    });
  }
  return days;
}

function dateISOForReq(r: RequisicaoQueue) {
  // Priorizar sempre a data de recebimento para agrupamento, depois data do pedido
  // O título pode conter uma data (byName), mas é apenas rótulo
  const byName = dateISOFromName(r.nome);
  const iso =
    r.data_recebimento || r.data_pedido || byName || r.created_at.slice(0, 10);
  return iso;
}

function DayColumn({
  day,
  loading,
  children,
  onPrint,
  isMobile,
  isToday,
  itemCount,
}: {
  day: { key: string; date: Date; dateISO: string; label: string };
  loading: boolean;
  children: React.ReactNode;
  onPrint: () => void;
  isMobile?: boolean;
  isToday?: boolean;
  itemCount?: number;
}) {
  const { setNodeRef, isOver } = useDroppable({ id: day.dateISO });
  return (
    <div
      className={classNames(
        'relative rounded-2xl border overflow-hidden transition-all duration-300 flex flex-col',
        'bg-white/85 dark:bg-zinc-900/60 backdrop-blur-xl',
        isToday
          ? 'border-[#57715B]/50 shadow-[0_0_0_1px_rgba(87,113,91,0.15),0_8px_30px_rgba(87,113,91,0.12)]'
          : 'border-zinc-200/80 dark:border-white/10 shadow-[0_1px_3px_rgba(0,0,0,0.04),0_4px_16px_rgba(0,0,0,0.04)] hover:border-zinc-300 dark:hover:border-white/20 hover:shadow-[0_2px_6px_rgba(0,0,0,0.06),0_8px_24px_rgba(0,0,0,0.06)]',
        isOver && 'ring-2 ring-[#57715B]/40 scale-[1.01]',
        isMobile ? 'h-[calc(100dvh-240px)]' : 'h-[calc(100vh-260px)] min-h-[520px] max-h-[760px]',
      )}
    >
      {/* Soft gradient overlay */}
      <div className="absolute inset-0 bg-gradient-to-br from-white/30 via-transparent to-zinc-100/30 dark:from-white/5 dark:to-black/20 pointer-events-none" />

      <div className="relative z-10 px-4 py-3 border-b border-zinc-200/70 dark:border-white/10 backdrop-blur-sm">
        <div className="flex items-center justify-between gap-2">
          <button
            onClick={onPrint}
            className="flex items-center gap-2 min-w-0 text-left group"
          >
            {isToday && (
              <span className="inline-flex h-2 w-2 rounded-full bg-[#57715B] animate-pulse flex-shrink-0" />
            )}
            <span
              className={classNames(
                'text-sm font-semibold tracking-tight truncate group-hover:text-[#57715B] transition-colors',
                isToday ? 'text-[#57715B] dark:text-emerald-400' : 'text-foreground',
              )}
            >
              {day.label}
            </span>
            {typeof itemCount === 'number' && itemCount > 0 && (
              <span className="inline-flex items-center justify-center min-w-[20px] h-5 px-1.5 rounded-full bg-[#57715B]/10 text-[#57715B] dark:bg-emerald-900/30 dark:text-emerald-400 text-[10px] font-bold flex-shrink-0">
                {itemCount}
              </span>
            )}
          </button>
          <Button data-mia-action="on-print"
            variant="ghost"
            size="sm"
            className="rounded-full h-8 w-8 p-0 text-muted-foreground hover:text-[#57715B] hover:bg-[#57715B]/10 flex-shrink-0"
            onClick={onPrint}
            aria-label="Imprimir dia"
          >
            <Printer className="w-3.5 h-3.5" />
          </Button>
        </div>
      </div>
      <div
        ref={setNodeRef}
        className={classNames(
          'relative z-10 p-3 space-y-2.5 flex-1 overflow-y-auto custom-scrollbar',
          isOver && 'bg-[#57715B]/5',
        )}
      >
        {loading && (
          <div className="animate-pulse h-24 rounded-xl bg-white/40 dark:bg-zinc-800/40 border border-white/30 dark:border-white/5" />
        )}
        {children}
      </div>
    </div>
  );
}

function ReqCard({
  req,
  displayDateISO,
  onClick,
  factoryName = 'Fábrica',
  isMobile,
}: {
  req: RequisicaoQueue;
  displayDateISO?: string;
  onClick: () => void;
  factoryName?: string;
  isMobile?: boolean;
}) {
  const itens = req.requisicoes_itens || [];
  const createdSource = (() => {
    const s = String(req.created_at || '');
    const hasTime = /[T\s]\d{2}:\d{2}/.test(s);
    if (hasTime) return s;
    const itTs = String(itens[0]?.created_at || '');
    return itTs || s;
  })();
  const createdTime = formatTime(createdSource);
  const entrega = parseISODateLocal(
    displayDateISO || req.data_recebimento || req.data_pedido,
  );
  const entregaDia = entrega.toLocaleDateString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    weekday: 'short',
  });
  const entregaData = entrega.toLocaleDateString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit',
    month: '2-digit',
  });

  const normalizedStatus = normalizeRequisicaoStatus(req.status);
  // Mapeamento direto do status do banco para o status visual
  // em_fila -> aberta (azul)
  // em_progresso -> progresso (laranja)
  // finalizada -> finalizada (verde)
  const status: 'aberta' | 'progresso' | 'finalizada' =
    normalizedStatus === 'finalizada'
      ? 'finalizada'
      : normalizedStatus === 'em_progresso'
        ? 'progresso'
        : 'aberta';

  const nameDateISO = coerceISODateString(
    displayDateISO || req.data_recebimento || req.data_pedido || '',
  );
  const nameDateLabel = formatDateDDMMYY(nameDateISO);
  const displayName = `Requisição - ${req.loja_solicitante} - ${nameDateLabel}`;

  // ─── MIA selector ──────────────────────────────────────────
  // Permite MIA identificar e clicar em uma requisição específica
  // via: "abrir requisição asa norte de hoje" → data-mia-action
  // resolve por (loja_slug, data_iso).
  const lojaSlug = (req.loja_solicitante || '')
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  const miaAction = `abrir-requisicao-${lojaSlug}-${nameDateISO}`;

  const statusStyles = {
    finalizada: {
      barGradient: 'from-emerald-500 to-emerald-400',
      dotColor: 'bg-emerald-500',
      badge: 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-800/50',
      badgeLabel: 'Finalizada',
      glow: 'hover:shadow-[0_8px_30px_rgba(16,185,129,0.18)]',
      accentOverlay: 'from-emerald-500/[0.04] via-transparent to-transparent',
    },
    progresso: {
      barGradient: 'from-amber-500 to-orange-400',
      dotColor: 'bg-amber-500',
      badge: 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-800/50',
      badgeLabel: 'Em Progresso',
      glow: 'hover:shadow-[0_8px_30px_rgba(245,158,11,0.18)]',
      accentOverlay: 'from-amber-500/[0.04] via-transparent to-transparent',
    },
    aberta: {
      barGradient: 'from-sky-500 to-blue-400',
      dotColor: 'bg-sky-500',
      badge: 'bg-sky-50 text-sky-700 border-sky-200 dark:bg-sky-900/30 dark:text-sky-300 dark:border-sky-800/50',
      badgeLabel: 'Na Fila',
      glow: 'hover:shadow-[0_8px_30px_rgba(96,165,250,0.18)]',
      accentOverlay: 'from-sky-500/[0.04] via-transparent to-transparent',
    },
  }[status];

  return (
    <button
      data-mia-action={miaAction}
      data-mia-loja={req.loja_solicitante}
      data-mia-data={nameDateISO}
      data-mia-status={status}
      data-mia-req-id={req.id}
      aria-label={displayName}
      onClick={onClick}
      className={classNames(
        'group relative w-full text-left rounded-xl overflow-hidden transition-all duration-300',
        'bg-white/95 dark:bg-zinc-900/70 backdrop-blur-xl',
        'border border-zinc-200/80 dark:border-white/10',
        'shadow-[0_1px_3px_rgba(0,0,0,0.04),0_2px_8px_rgba(0,0,0,0.04)] hover:-translate-y-0.5 hover:border-zinc-300 dark:hover:border-white/20',
        statusStyles.glow,
        isMobile ? 'min-h-[100px]' : 'min-h-[120px]',
      )}
    >
      {/* Status bar lateral */}
      <div
        className={classNames(
          'absolute left-0 top-0 bottom-0 w-1 bg-gradient-to-b',
          statusStyles.barGradient,
        )}
      />

      {/* Soft gradient overlay */}
      <div
        className={classNames(
          'absolute inset-0 pointer-events-none bg-gradient-to-br',
          statusStyles.accentOverlay,
        )}
      />

      {/* Conteúdo */}
      <div className={classNames('relative z-10', isMobile ? 'pl-3 pr-3 py-2.5' : 'pl-4 pr-3 py-3')}>
        {/* Header: loja origem → destino + badge */}
        <div className="flex items-start justify-between gap-2 mb-2">
          <div className="flex items-center gap-1.5 min-w-0 flex-1">
            <Truck className="w-3 h-3 text-[#57715B] dark:text-emerald-400 flex-shrink-0" />
            <span className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground truncate">
              {factoryName} → {req.loja_solicitante}
            </span>
          </div>
          <span
            className={classNames(
              'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider border flex-shrink-0',
              statusStyles.badge,
            )}
          >
            <span className={classNames('w-1 h-1 rounded-full', statusStyles.dotColor)} />
            {statusStyles.badgeLabel}
          </span>
        </div>

        {/* Título */}
        <div className="text-sm font-bold text-foreground leading-snug line-clamp-2 mb-1.5">
          {displayName}
        </div>

        {req.subtitle && (
          <div className="text-[11px] text-muted-foreground line-clamp-1 mb-1.5">
            {req.subtitle}
          </div>
        )}

        {/* Metadata grid */}
        <div className="grid grid-cols-2 gap-x-2 gap-y-0.5 text-[10px] text-muted-foreground">
          <div className="flex items-center gap-1 min-w-0">
            <span className="font-semibold text-foreground/70">Solicitante:</span>
            <span className="truncate">{req.solicitante}</span>
          </div>
          <div className="flex items-center gap-1 min-w-0 justify-end">
            <Package className="w-2.5 h-2.5" />
            <span className="font-bold text-foreground/80">{itens.length || 0}</span>
            <span>itens</span>
          </div>
          {req.lancado_por && (
            <div className="flex items-center gap-1 min-w-0 col-span-2">
              <span className="font-semibold text-foreground/70">Por:</span>
              <span className="truncate">{req.lancado_por}</span>
              <span className="ml-auto text-[9px] text-muted-foreground/70">
                às {createdTime}
              </span>
            </div>
          )}
        </div>
      </div>
    </button>
  );
}

function DraggableReq({
  req,
  displayDateISO,
  onClick,
  factoryName,
  isMobile,
}: {
  req: RequisicaoQueue;
  displayDateISO?: string;
  onClick: () => void;
  factoryName: string;
  isMobile: boolean;
}) {
  const { attributes, listeners, setNodeRef, transform } = useDraggable({
    id: req.id,
  });
  const style = {
    transform: transform ? CSS.Translate.toString(transform) : undefined,
    zIndex: transform ? 50 : undefined,
    opacity: transform ? 0.95 : 1,
  } as React.CSSProperties;
  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="relative"
    >
      <ReqCard
        req={req}
        displayDateISO={displayDateISO}
        onClick={onClick}
        factoryName={factoryName}
        isMobile={isMobile}
      />
    </div>
  );
}

export default function Logistica() {
  useMiaPageContext({
    description: 'Logística do Momma — Torre de Controle (distribuição fábrica→lojas), requisições, separação por etiqueta QR, recebimento.',
    natural_language_hints: '"requisitar X" = nova requisição (NÃO dispara expedição automática); "separar" = /logistica/separacao-bip; "receber" = /logistica/recebimento; "torre" = distribuição. Etiquetas QR são UID único.',
    capabilities: ['criar_requisicao', 'separar_pedido', 'receber_carga', 'imprimir_relatorio'],
    primary_entity: 'requisicao',
  });
  const navigate = useNavigate();
  const { canViewLogistica } = usePermissions();
  const isMobile = useIsMobile();
  const isTablet = useIsTablet();
  const telemetryAttrs = useTelemetryAttrs();
  const [viewMode, setViewMode] = useState<'kanban' | 'lista' | 'analytics'>(
    () => {
      try {
        const v =
          typeof window !== 'undefined'
            ? localStorage.getItem('logistica_view_mode')
            : null;
        return v === 'lista'
          ? 'lista'
          : v === 'analytics'
            ? 'analytics'
            : 'kanban';
      } catch {
        return 'kanban';
      }
    },
  );
  const [loading, setLoading] = useState(false);
  const [requisicoes, setRequisicoes] = useState<RequisicaoQueue[]>([]);
  const [showReportsModal, setShowReportsModal] = useState(false);

  const [selectedReqId, setSelectedReqId] = useState<number | null>(null);
  const selectedReq = useMemo(
    () =>
      selectedReqId
        ? requisicoes.find((r) => r.id === selectedReqId) || null
        : null,
    [selectedReqId, requisicoes],
  );
  const { stores } = useStore();
  // PADRONIZADO: Usar os 3 status do banco diretamente
  const [statusFilter, setStatusFilter] = useState<
    Array<'em_fila' | 'em_progresso' | 'finalizada'>
  >(['em_fila', 'em_progresso']);
  const [lojaFilter, setLojaFilter] = useState<string>('todas');

  const [weekDays, setWeekDays] = useState<
    { key: string; date: Date; dateISO: string; label: string }[]
  >(() => {
    const start = new Date();
    start.setDate(start.getDate() - 14);
    return buildDays(start, 42);
  });
  const grouped = useMemo(() => {
    const map: Record<string, RequisicaoQueue[]> = {};
    weekDays.forEach((d) => {
      map[d.dateISO] = [];
    });
    requisicoes.forEach((r) => {
      const iso = dateISOForReq(r);
      if (map[iso]) map[iso].push(r);
    });
    return map;
  }, [requisicoes, weekDays]);

  const factoryName = useMemo(() => {
    const f = stores.find(
      (s) =>
        String(s.tipo || '').toLowerCase() === 'fabrica' ||
        String(s.name || '')
          .toLowerCase()
          .includes('fábrica') ||
        String(s.name || '')
          .toLowerCase()
          .includes('fabrica'),
    );
    return f?.name || 'Fábrica';
  }, [stores]);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 },
    }),
  );
  const orderById = useMemo(() => {
    const m = new Map<number, RequisicaoQueue>();
    requisicoes.forEach((r) => m.set(r.id, r));
    return m;
  }, [requisicoes]);
  const [activeId, setActiveId] = useState<number | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const initialFocusDone = useRef<boolean>(false);
  const handleBack = useCallback(() => {
    navigate('/dashboard');
  }, [navigate]);

  const onDragStart = (ev: DragStartEvent) => {
    if (ev.active?.id) setActiveId(Number(ev.active.id));
  };
  const moveReq = async (req: RequisicaoQueue, newDateISO: string) => {
    try {
      const dateLabel = formatDateDDMMYY(newDateISO);
      const newName = `Requisição - ${req.loja_solicitante} - ${dateLabel}`;
      setRequisicoes((cur) =>
        cur.map((r) =>
          r.id === req.id
            ? { ...r, data_recebimento: newDateISO, nome: newName }
            : r,
        ),
      );
      const { error } = await supabase
        .from('requisicoes')
        .update({ data_recebimento: newDateISO, nome: newName })
        .eq('id', req.id);
      if (error) throw error;
      wideInfo('logistica.requisicao.movida', 'Requisição movida para nova data', enrichWideEvent('logistica', {
        'requisicao.id': req.id,
        'requisicao.status': req.status,
        'requisicao.loja_solicitante': req.loja_solicitante,
        'requisicao.loja': req.loja_solicitante,
        'requisicao.nova_data': newDateISO,
      }));
      toast.success('Dia atualizado');
    } catch (e) {
      wideError('logistica.requisicao.erro', 'Erro ao mover requisição', enrichWideEvent('logistica', {
        'error.message': e instanceof Error ? e.message : 'Erro ao mover requisição',
        'requisicao.id': req.id,
        'requisicao.status': req.status,
        'requisicao.loja_solicitante': req.loja_solicitante,
        'requisicao.operacao': 'mover',
      }));
      recordError('logistica_requisicao', 'mover');
      toast.error('Erro ao mover requisição');
      fetchQueue();
    }
  };
  const onDragEnd = (ev: DragEndEvent) => {
    const { active, over } = ev;
    if (over && active?.id) {
      const req = orderById.get(Number(active.id));
      const newDateISO = String(over.id);
      if (req) moveReq(req, newDateISO);
    }
    setActiveId(null);
  };
  const onDragCancel = () => setActiveId(null);
  const dropAnimation = {
    duration: 90,
    easing: 'cubic-bezier(0.2, 0, 0, 1)',
  } as any;

  const lastAppendRef = useRef<number>(0);
  const appendMoreDays = useCallback((count = 14) => {
    const now = Date.now();
    if (now - (lastAppendRef.current || 0) < 600) return;
    lastAppendRef.current = now;
    setWeekDays((prev) => {
      const last = prev[prev.length - 1]?.date || startOfWeek(new Date());
      const start = new Date(last);
      start.setDate(start.getDate() + 1);
      const more = buildDays(start, count);
      return [...prev, ...more];
    });
  }, []);

  const lastPrependRef = useRef<number>(0);
  const prependMoreDays = useCallback((count = 14) => {
    const now = Date.now();
    if (now - (lastPrependRef.current || 0) < 600) return;
    lastPrependRef.current = now;
    setWeekDays((prev) => {
      const first = prev[0]?.date || new Date();
      const end = new Date(first);
      end.setDate(end.getDate() - 1);
      const start = new Date(end);
      start.setDate(start.getDate() - count + 1);
      const more = buildDays(start, count);
      return [...more, ...prev];
    });
    // Maintain scroll position after prepend
    requestAnimationFrame(() => {
      const el = scrollRef.current;
      if (el) {
        const colWidth = 180;
        el.scrollLeft += colWidth * count;
      }
    });
  }, []);

  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    const onScroll = () => {
      const threshold = 80;
      // Scroll right — append future days
      if (el.scrollLeft + el.clientWidth >= el.scrollWidth - threshold) {
        appendMoreDays();
      }
      // Scroll left — prepend past days
      if (el.scrollLeft <= threshold) {
        prependMoreDays();
      }
    };
    el.addEventListener('scroll', onScroll);
    return () => el.removeEventListener('scroll', onScroll);
  }, [appendMoreDays, prependMoreDays]);

  useEffect(() => {
    try {
      localStorage.setItem('logistica_view_mode', viewMode);
    } catch {
      /* intentional */
    }
  }, [viewMode]);

  useEffect(() => {
    if (viewMode !== 'kanban') return;
    if (initialFocusDone.current) return;
    const el = scrollRef.current;
    if (!el) return;
    const todayISO = (() => {
      const d = new Date();
      const br = d.toLocaleDateString('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
      });
      const [day, month, year] = br.split('/');
      return `${year}-${month}-${day}`;
    })();
    const target = el.querySelector(
      `[data-date-iso="${todayISO}"]`,
    ) as HTMLElement | null;
    if (target) {
      target.scrollIntoView({
        behavior: 'auto',
        inline: 'center',
        block: 'nearest',
      });
      initialFocusDone.current = true;
    }
  }, [weekDays, viewMode]);

  useEffect(() => {
    if (viewMode !== 'lista') return;
    const onWindowScroll = () => {
      const threshold = 120;
      if (
        window.innerHeight + window.scrollY >=
        document.body.scrollHeight - threshold
      ) {
        appendMoreDays();
      }
    };
    window.addEventListener('scroll', onWindowScroll);
    return () => window.removeEventListener('scroll', onWindowScroll);
  }, [viewMode, appendMoreDays]);

  const fetchQueue = useCallback(async () => {
    setLoading(true);
    await withTrace('logistica.fila.carregar', async () => {
      const startTime = performance.now();
      try {
        // PADRONIZADO: Usar os 3 status do banco diretamente (em_fila, em_progresso, finalizada)
        const selected = statusFilter.length
          ? statusFilter
          : ['em_fila', 'em_progresso', 'finalizada'];

        // Buscar requisições filtrando pelo campo status diretamente
        const { data: reqs, error } = await supabase
          .from('requisicoes')
          .select(
            `id, nome, solicitante, loja_solicitante, loja_preparadora, data_pedido, data_recebimento, created_at, status, user_id, subtitle, expedicao_id, requisicoes_itens(*)`,
          )
          .in('status', selected)
          .order('created_at', { ascending: false });

        if (error) throw error;
        const result = (reqs as any[]) || [];

        let filtered = result;
        if (lojaFilter !== 'todas') {
          const lojaName = (() => {
            const found = stores.find((s) => String(s.id) === String(lojaFilter));
            return found?.name || '';
          })();
          filtered = filtered.filter((r) => r.loja_solicitante === lojaName);
        }

        {
          const userIds = Array.from(
            new Set((filtered || []).map((r: any) => r.user_id).filter(Boolean)),
          );
          const namesMap: Record<string, string> = {};
          await Promise.all(
            userIds.map(async (uid) => {
              const { data: userName } = await supabase.rpc(
                'get_user_display_name',
                { user_uuid: uid },
              );
              if (uid) namesMap[uid] = userName || '';
            }),
          );
          const withNames = (filtered || []).map((r: any) => ({
            ...r,
            lancado_por: r.user_id ? namesMap[r.user_id] || '' : '',
          }));
          setRequisicoes(withNames as any);
        }

        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('logistica.fila.carregada', 'Fila de requisições carregada', enrichWideEvent('logistica', {
          'expedicao.loja_origem': factoryName,
          'requisicao.status': selected.join(','),
          'requisicao.loja_solicitante': lojaFilter,
          result_count: filtered.length,
          duration_ms: durationMs,
          'filtro.status': selected.join(','),
          'filtro.loja': lojaFilter,
        }));
        recordOperation('logistica.fila');
        recordOperationDuration('logistica.fila', durationMs);
      } catch {
        // PADRONIZADO: Fallback usando status do banco diretamente
        try {
          const selected = statusFilter.length
            ? statusFilter
            : ['em_fila', 'em_progresso', 'finalizada'];

          const { data: reqs } = await supabase
            .from('requisicoes')
            .select(
              'id, nome, solicitante, loja_solicitante, loja_preparadora, data_pedido, data_recebimento, created_at, status, user_id, subtitle',
            )
            .in('status', selected)
            .order('created_at', { ascending: false });

          let filtered = (reqs as any[]) || [];
          if (lojaFilter !== 'todas') {
            const lojaName = (() => {
              const found = stores.find(
                (s) => String(s.id) === String(lojaFilter),
              );
              return found?.name || '';
            })();
            filtered = filtered.filter((r) => r.loja_solicitante === lojaName);
          }
          {
            const userIds = Array.from(
              new Set(
                (filtered || []).map((r: any) => r.user_id).filter(Boolean),
              ),
            );
            const namesMap: Record<string, string> = {};
            await Promise.all(
              userIds.map(async (uid) => {
                const { data: userName } = await supabase.rpc(
                  'get_user_display_name',
                  { user_uuid: uid },
                );
                if (uid) namesMap[uid] = userName || '';
              }),
            );
            const withNames = (filtered || []).map((r: any) => ({
              ...r,
              lancado_por: r.user_id ? namesMap[r.user_id] || '' : '',
            }));
            setRequisicoes(withNames as any);
          }

          const durationMs = Math.round(performance.now() - startTime);
          wideInfo('logistica.fila.carregada', 'Fila de requisições carregada via fallback', enrichWideEvent('logistica', {
            'expedicao.loja_origem': factoryName,
            'requisicao.status': selected.join(','),
            'requisicao.loja_solicitante': lojaFilter,
            result_count: filtered.length,
            duration_ms: durationMs,
            'filtro.status': selected.join(','),
            'filtro.loja': lojaFilter,
            fallback: true,
          }));
        } catch {
          const durationMs = Math.round(performance.now() - startTime);
          wideError('logistica.fila.erro', 'Falha ao carregar fila de requisições', enrichWideEvent('logistica', {
            'error.message': 'Falha ao carregar fila de requisições',
            'expedicao.loja_origem': factoryName,
            'requisicao.status': statusFilter.join(','),
            'requisicao.loja_solicitante': lojaFilter,
            duration_ms: durationMs,
          }));
          recordError('logistica_fila', 'carregar');
          setRequisicoes([]);
        }
      } finally {
        setLoading(false);
      }
    }, telemetryAttrs);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [statusFilter, lojaFilter, stores]);

  useEffect(() => {
    fetchQueue();
  }, [fetchQueue]);

  const printDayOrders = (dateISO: string, label: string) => {
    const items = grouped[dateISO] || [];
    const rows = items
      .map((r) => {
        const iso = coerceISODateString(
          r.data_recebimento || r.data_pedido || '',
