        const lbl = formatDateDDMMYY(iso);
        const nm = `Requisição - ${r.loja_solicitante} - ${lbl}`;
        return `<tr><td>${r.id}</td><td>${nm}</td><td>${r.solicitante}</td></tr>`;
      })
      .join('');
    const html = `<!DOCTYPE html><html><head><title>Requisições – ${label}</title><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"></head><body><h1>Requisições ${label}</h1><table border=1 style="border-collapse:collapse;width:100%"><tr><th>ID</th><th>Nome</th><th>Solicitante</th></tr>${rows}</table></body></html>`;
    printHTML(html, { title: `Requisições – ${label}` });
  };

  const openDetails = (req: RequisicaoQueue) => {
    setSelectedReqId(req.id);
  };

  const todayISO = useMemo(() => {
    const d = new Date();
    const br = d.toLocaleDateString('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
