    return `${year}-${month}-${day}`;
  }, []);

  return (
    <PermissionBlur hasPermission={canViewLogistica()} moduleName="Logística">
      <div
        className="min-h-screen w-full bg-white dark:bg-[#0A0A0A] font-sans relative overflow-x-hidden transition-colors duration-300"
        data-mia-page="logistica"
        data-mia-domain="logistica"
      >
        {/* Faixa de toldo Momma no topo */}
        <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50 shadow-sm pointer-events-none" />

        {/* Ícones decorativos animados de fundo */}
        <div
          className="fixed top-[5%] left-[3%] w-[350px] md:w-[500px] h-[350px] md:h-[500px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
          style={{ animationDuration: '14s' }}
          aria-hidden="true"
        >
          <Truck className="w-full h-full text-[#57715B] -rotate-6" />
        </div>
        <div
          className="fixed bottom-[-8%] right-[3%] w-[400px] md:w-[600px] h-[400px] md:h-[600px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse delay-1000"
          style={{ animationDuration: '16s' }}
          aria-hidden="true"
        >
          <Leaf className="w-full h-full text-[#C5A065] rotate-[20deg]" />
        </div>
        <div
          className="fixed top-[40%] right-[25%] w-[200px] md:w-[300px] h-[200px] md:h-[300px] opacity-[0.02] dark:opacity-[0.04] pointer-events-none animate-pulse delay-500"
          style={{ animationDuration: '18s' }}
          aria-hidden="true"
        >
          <Package className="w-full h-full text-[#57715B] rotate-[-12deg]" />
        </div>

        {/* Soft ambient glows */}
        <div className="fixed top-[10%] left-[20%] w-[300px] md:w-[500px] h-[300px] md:h-[500px] bg-emerald-500/5 rounded-full blur-[100px] pointer-events-none" />
        <div className="fixed bottom-[15%] right-[15%] w-[250px] md:w-[450px] h-[250px] md:h-[450px] bg-amber-500/5 rounded-full blur-[100px] pointer-events-none" />

        {/* Container principal */}
        <div
          className={classNames(
            'relative z-10 w-full max-w-[1800px] mx-auto animate-in fade-in duration-500',
            isMobile ? 'px-3 pt-3 pb-6 tablet:px-6 tablet:pt-5 tablet:pb-8' : 'px-4 sm:px-6 lg:px-8 pt-6 pb-10',
          )}
        >
        {isMobile ? (
          <div className="space-y-3 mb-4 tablet:space-y-4 tablet:mb-5">
