              >
                <ArrowLeft className="h-5 w-5 tablet:h-6 tablet:w-6" />
              </Button>
              <div className="flex items-center gap-2.5 min-w-0 flex-1 tablet:gap-4">
                <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#57715B]/10 border border-[#57715B]/20 flex-shrink-0 tablet:h-12 tablet:w-12 tablet:rounded-2xl">
                  <ClipboardList className="h-5 w-5 text-[#57715B] dark:text-emerald-400 tablet:h-6 tablet:w-6" />
                </div>
                <div className="min-w-0">
                  <h1 className="text-lg font-bold tracking-tight text-foreground truncate tablet:text-2xl">
                    Logística
                  </h1>
                  <p className="text-[11px] text-muted-foreground truncate tablet:text-sm">
                    {requisicoes.length} requisições · Fila e quadro
                    {isTablet && ' · em tempo real'}
