interface ReqChegada {
  id: number;
  nome: string;
  loja_solicitante: string;
  loja_preparadora: string;
  data_pedido: string;
  data_recebimento: string;
  status: string | null;
  chegada_iniciada_at: string | null;
  chegada_concluida_at: string | null;
}

