/**
 * @module DashboardStoreSelector
 *
 * Seletor de loja integrado ao StoreContext para uso no dashboard.
 * Exibe dropdown com troca de loja para admins e apenas o nome
 * da loja para usuários sem permissão de troca.
 */

import { Check, ChevronDown, Store } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import { useStore } from "@/shared/contexts/StoreContext";
import { usePermissions } from "@/shared/hooks/usePermissions";
import { cn } from '@/shared/lib/utils';

interface StoreSelectorProps {
  compact?: boolean;
  className?: string;
}

export function StoreSelector({ compact = false, className }: StoreSelectorProps = {}) {
  const { selectedStore, setSelectedStore, stores, canChangeStore, loading } =
    useStore();
  const { isAdmin } = usePermissions();

  // Verificação dupla: canChangeStore OU isAdmin
  const userCanChangeStore = canChangeStore || isAdmin();

  const triggerLabel = selectedStore?.shortName || 'Loja';
  const baseClasses = compact
    ? 'h-8 w-8 p-0 justify-center bg-background/50 border-border/50'
    : 'h-8 px-2.5 gap-2 bg-background/50 border-border/50 w-full justify-start';

  if (loading || !selectedStore) {
    return (
      <Button
        variant="outline"
        className={cn(baseClasses, className)}
        disabled
        title="Carregando..."
      >
        <Store className="h-4 w-4 text-primary" />
        {!compact && <span className="font-medium text-sm">Carregando...</span>}
      </Button>
    );
  }

  // Se o usuário não pode alterar loja, mostrar apenas o nome da loja
  if (!userCanChangeStore) {
    return (
      <Button
        variant="outline"
        className={cn(baseClasses, 'cursor-default', className)}
        disabled
        title={selectedStore.name}
      >
        <Store className="h-4 w-4 text-primary" />
        {!compact && (
          <span className="font-medium text-sm truncate">{triggerLabel}</span>
        )}
      </Button>
    );
  }

  // Para administradores, mostrar o seletor completo
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="outline"
          className={cn(
            baseClasses,
            'hover:bg-accent/50 transition-colors',
            className,
          )}
          title={selectedStore.name}
        >
          <Store className="h-4 w-4 text-primary shrink-0" />
          {!compact && (
            <>
              <span className="font-medium text-sm truncate flex-1 text-left">
                {triggerLabel}
              </span>
              <ChevronDown className="h-3 w-3 text-muted-foreground shrink-0" />
            </>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-56">
        {stores.map((store) => (
          <DropdownMenuItem
            key={store.id}
            onClick={() => setSelectedStore(store)}
            className="flex items-center justify-between cursor-pointer"
          >
            <div className="flex items-center gap-2">
              <Store className="h-4 w-4 text-muted-foreground" />
              <div className="flex flex-col">
                <span className="text-sm font-medium">{store.name}</span>
                <span className="text-xs text-muted-foreground">
                  {store.address}
                </span>
              </div>
            </div>
            {selectedStore.id === store.id && (
              <Check className="h-4 w-4 text-primary" />
            )}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

