import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { useAuth } from './useAuth';
import { supabase } from '@/integrations/supabase/client';
import { wideError } from '@/shared/lib/telemetry/wide-events';
import { handleError } from '@/shared/lib/error-handler';

interface Permission {
  permission_name: string;
  permission_display_name: string;
  module: string;
}

interface UserRole {
  role_name: string;
  role_display_name: string;
  can_change_store: boolean;
}

interface PermissionsContextType {
  permissions: Permission[];
  userRole: UserRole | null;
  loading: boolean;
  hasPermission: (permissionName: string) => boolean;
  hasAnyPermission: (permissionNames: string[]) => boolean;
  isAdmin: () => boolean;
  canAccessModule: (module: string) => boolean;
  refreshPermissions: () => Promise<void>;
  canViewFinanceiro: () => boolean;
  canViewDashboard: () => boolean;
  canViewEstoque: () => boolean;
  canAdminPermissions: () => boolean;
  canViewLogistica: () => boolean;
  canViewRequisicao: () => boolean;
  canViewNotasFiscais: () => boolean;
  canViewEncomendas: () => boolean;
  canViewNCM: () => boolean;
  canViewEventos: () => boolean;
  canViewProntaEntrega: () => boolean;
  canViewMia: () => boolean;
  canSwitchStore: () => boolean;
  canSelectStoreNF: () => boolean;
}

const PermissionsContext = createContext<PermissionsContextType | undefined>(undefined);

export function PermissionsProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [userRole, setUserRole] = useState<UserRole | null>(null);
  const [profileSelectStoreNF, setProfileSelectStoreNF] = useState<boolean>(false);
  const [loading, setLoading] = useState(true);

  const fetchUserPermissions = async () => {
    if (!user) {
      setPermissions([]);
      setUserRole(null);
      setProfileSelectStoreNF(false);
      setLoading(false);
      return;
    }

    try {
      setLoading(true);

      // Buscar permissões do usuário
      const { data: permissionsData, error: permissionsError } = await supabase
        .rpc('get_user_permissions', { user_uuid: user.id });

      if (permissionsError) {
        wideError('permissions.fetch_error', 'Erro ao buscar permissões do usuário', {
          attributes: {
            'permissions.error_code': permissionsError.code,
            'permissions.error_message': permissionsError.message,
            'permissions.user_id': user.id,
          },
        });
        setPermissions([]);
      } else {
        setPermissions(permissionsData || []);
      }

      // Buscar role do usuário com can_change_store e flags de perfil
      const { data: profileData, error: profileError } = await supabase
        .from('profiles')
        .select('can_select_store_nf, user_roles(*)')
        .eq('user_id', user.id)
        .single();

      if (profileError) {
        wideError('permissions.role_fetch_error', 'Erro ao buscar role do usuário', {
          attributes: {
            'permissions.error_code': profileError.code,
            'permissions.error_message': profileError.message,
            'permissions.user_id': user.id,
          },
        });
        setUserRole(null);
        setProfileSelectStoreNF(false);
      } else {
        const role = profileData?.user_roles as { name: string; display_name: string; can_change_store: boolean } | null;
        setUserRole(role ? {
          role_name: role.name,
          role_display_name: role.display_name,
          can_change_store: role.can_change_store ?? false,
        } : null);
        setProfileSelectStoreNF(profileData?.can_select_store_nf ?? false);
      }
    } catch (error) {
      handleError(error, { domain: 'permissions', operation: 'fetchUserPermissions', showToast: false });
      setPermissions([]);
      setUserRole(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // Só buscar permissões se o usuário mudou realmente (não apenas re-renderizou)
    if (user && (!userRole || permissions.length === 0)) {
      fetchUserPermissions();
    } else if (!user) {
      // Limpar permissões se não há usuário
      setPermissions([]);
      setUserRole(null);
      setLoading(false);
    }
  }, [user?.id]); // Usar user.id ao invés de user para evitar re-renders desnecessários

  const hasPermission = (permissionName: string): boolean => {
    return permissions.some(p => p.permission_name === permissionName);
  };

  const hasAnyPermission = (permissionNames: string[]): boolean => {
    return permissionNames.some(permissionName => hasPermission(permissionName));
  };

  const isAdmin = (): boolean => {
    // Tornar detecção de admin resiliente a variações de nome/idioma
    const roleName = userRole?.role_name?.toLowerCase();
    const adminAliases = ['admin', 'administrador', 'administrator'];
    const result = roleName ? adminAliases.includes(roleName) : false;

    return result;
  };

  const canAccessModule = (module: string): boolean => {
    if (isAdmin()) return true;
    return permissions.some(p => p.module === module);
  };

  // Funções específicas para controle de acesso às páginas
  const canViewFinanceiro = (): boolean => {
    return hasPermission('view_financeiro') || isAdmin();
  };



  const canViewDashboard = (): boolean => {
    return hasPermission('view_dashboard') || isAdmin();
  };

  const canViewEstoque = (): boolean => {
    return canAccessModule('estoque');
  };

  const canAdminPermissions = (): boolean => {
    return hasPermission('admin_permissions') || isAdmin();
  };

  const canViewLogistica = (): boolean => {
    return hasPermission('view_logistica') || isAdmin();
  };

  const canViewRequisicao = (): boolean => {
    return hasPermission('view_requisicao') || isAdmin();
  };

  const canViewNotasFiscais = (): boolean => {
    return hasPermission('view_notas_fiscais') || isAdmin();
  };



  const canViewEncomendas = (): boolean => {
    return hasPermission('view_encomendas') || isAdmin();
  };

  const canViewNCM = (): boolean => {
    return hasPermission('view_ncm') || isAdmin();
  };

  const canViewEventos = (): boolean => {
    return hasPermission('view_eventos') || isAdmin();
  };

  const canSwitchStore = (): boolean => {
    if (isAdmin()) return true;
    return userRole?.can_change_store ?? false;
  };

  const canSelectStoreNF = (): boolean => {
    return isAdmin() || profileSelectStoreNF;
  };

  const refreshPermissions = async () => {
    await fetchUserPermissions();
  };

  const value: PermissionsContextType = {
    permissions,
    userRole,
    loading,
    hasPermission,
    hasAnyPermission,
    isAdmin,
    canAccessModule,
    refreshPermissions,
    canViewFinanceiro,
    canViewDashboard,
    canViewEstoque,
    canAdminPermissions,
    canViewLogistica,
    canViewRequisicao,
    canViewNotasFiscais,

    canViewEncomendas,
    canViewNCM,
    canViewEventos,
    canViewProntaEntrega: () => hasPermission('view_pronta_entrega') || isAdmin(),
    canViewMia: () => isAdmin(), // MIA visível APENAS para administradores
    canSwitchStore,
    canSelectStoreNF,
  };

  return (
    <PermissionsContext.Provider value={value}>
      {children}
    </PermissionsContext.Provider>
  );
}

export function usePermissions() {
  const context = useContext(PermissionsContext);
  if (context === undefined) {
    throw new Error('usePermissions deve ser usado dentro de um PermissionsProvider');
  }
  return context;
}

// Hook para verificar permissões específicas
export function useRequirePermission(permissionName: string) {
  const { hasPermission, loading } = usePermissions();

  return {
    hasAccess: hasPermission(permissionName),
    loading
  };
}

// Hook para verificar acesso a módulos
export function useRequireModule(module: string) {
  const { canAccessModule, loading } = usePermissions();

  return {
    hasAccess: canAccessModule(module),
    loading
  };
}

